/**
 * Parse macros  (универсально для:
 *  – старого jsonOutput: true
 *  – нового Structured Output Parser c массивом или без)
 */

// 1. данные от Split weight (chat_id, grams, draft_id, …)
const sw = $items('Split weight')[0].json;

// 2. что пришло от LLM / parser
//    – если это массив → берём первый элемент
//    – если внутри есть .output → берём его, иначе сам объект
const raw = Array.isArray($json) ? $json[0] : $json;
const gpt = raw.output ?? raw;       // { dish, kcal, prot, fat, carb }

// 3. helper → строка даты-времени в МСК ISO +03:00
const toMsk = () => {
  const msk = new Date(
    new Date().toLocaleString('en-US', { timeZone: 'Europe/Moscow' })
  );
  const p = n => String(n).padStart(2, '0');
  return `${msk.getFullYear()}-${p(msk.getMonth() + 1)}-${p(msk.getDate())}` +
         `T${p(msk.getHours())}:${p(msk.getMinutes())}:00+03:00`;
};

// 4. собираем итоговый объект (плоский)
return [{
