const raw = Array.isArray(items[0].json) ? items[0].json[0] : items[0].json;
let meals = raw.candidates;
if (typeof meals === 'string') meals = JSON.parse(meals);
if (!Array.isArray(meals)) throw new Error('В draft нет списка блюд');

const ctx = $items('Parse multi confirm')[0].json;
const msk = new Date(new Date().toLocaleString('en-US',{timeZone:'Europe/Moscow'}));
const p=n=>String(n).padStart(2,'0');
const eaten_at = `${msk.getFullYear()}-${p(msk.getMonth()+1)}-${p(msk.getDate())}T${p(msk.getHours())}:${p(msk.getMinutes())}:00+03:00`;

const selected=meals.filter(m=>m.included!==false);
if(!selected.length){
  // No included items = user intentionally excluded the whole draft.
  return [{json:{
    chat_id:ctx.chat_id,
    draft_id:ctx.draft_id,
    skip_save:true,
    dish:'',
    grams:0,kcal:0,prot:0,fat:0,carb:0,
    eaten_at
  }}];
}

return selected.map(m => ({json:{
  chat_id:ctx.chat_id,
  draft_id:ctx.draft_id,
  dish:m.dish,
  grams:Number(m.grams),
  kcal:Number(m.kcal),
  prot:Number(m.prot),
  fat:Number(m.fat),
  carb:Number(m.carb),
  eaten_at: m.eaten_at || eaten_at
}}));

const rows = items.map(i => i.json);
const ctx = $items('Parse multi confirm')[0].json;
const totals = rows.reduce((a,r)=>({
  kcal:a.kcal+Number(r.kcal||0),
  prot:a.prot+Number(r.prot||0),
  fat:a.fat+Number(r.fat||0),
  carb:a.carb+Number(r.carb||0)
}),{kcal:0,prot:0,fat:0,carb:0});

return [{json:{
  chat_id:ctx.chat_id,
  msg_id:ctx.del_msg_id,
  count:rows.length,
  kcal:Math.round(totals.kcal),
  prot:Math.round(totals.prot*10)/10,
  fat:Math.round(totals.fat*10)/10,
  carb:Math.round(totals.carb*10)/10
}}];

const upd=$items("When Executed by Ingress")[0].json.message;
const cap=$items("Parse photo caption")[0].json;
const chatId=upd.chat.id;
const msgId=upd.message_id;
const photoId=upd.photo[upd.photo.length-1].file_id;

let raw=$json.content??$json.message?.content??$json;
if(typeof raw!=='string')raw=JSON.stringify(raw);

raw=raw
  .replace(/```json/gi,'')
  .replace(/```/g,'')
  .replace(/[“”]/g,'"')
  .replace(/[‘’]/g,"'")
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'')
  .trim();

const a=raw.indexOf('{'),b=raw.lastIndexOf('}');
if(a>=0&&b>a)raw=raw.slice(a,b+1);
raw=raw.replace(/,\s*([}\]])/g,'$1');

let parsed=null;
try{parsed=JSON.parse(raw)}catch(_){}

const arr=parsed&&Array.isArray(parsed.items)?parsed.items:[];
const containers=Number(parsed?.containers_detected||0);

const num=v=>{
  if(v===null||v===undefined||v==='')return null;
  const n=Number(String(v).replace(',','.').replace(/[^\d.+-]/g,''));
  return Number.isFinite(n)?n:null;
};
const txt=v=>String(v??'').replace(/["“”]/g,'').replace(/\s+/g,' ').trim();

const captionGrams=Number(cap.caption_grams||0)>0?Number(cap.caption_grams):null;
const captionHint=String(cap.caption_identity_hint||'').trim();
const captionHasIdentity=Boolean(cap.caption_has_identity&&captionHint);

function textHasNumber(text,value,tolerance=0.06){
  if(value===null||value===undefined)return false;
  const nums=String(text||'').replace(/,/g,'.').match(/\d+(?:\.\d+)?/g)||[];
  const target=Number(value);
  return nums.some(s=>{
    const n=Number(s);
    return Number.isFinite(n)&&Math.abs(n-target)<=Math.max(0.11,Math.abs(target)*tolerance);
  });
}

const clean=arr.map((x,i)=>{
  let mode=String(x.source_mode||'visual').toLowerCase();
  if(!['label','web','visual'].includes(mode))mode='visual';

  const labelName=txt(x.label_name||x.package_name);
  const packageContext=Boolean(x.package_context);
  let dish=txt((packageContext&&labelName)||x.dish||x.name||x.label);
  // Explicit user wording outranks model guesses such as SPAR -> Мираторг.
  if(captionHasIdentity && arr.length===1) dish=captionHint;
  const packageText=txt(x.package_text);
  const labelText=txt(x.label_text);
  const evidenceText=`${packageText} ${labelText}`;

  const labelKcal=num(x.label_kcal);
  const labelProt=num(x.label_prot);
  const labelFat=num(x.label_fat);
  const labelCarb=num(x.label_carb);

  const completeLabel=[labelKcal,labelProt,labelFat,labelCarb].every(v=>v!==null);

  // Evidence guard:
  // for label mode, at least 3 of 4 extracted nutrition numbers must also be visible
  // in the OCR transcript. This prevents "confident" hallucinated macros.
  const evidenceHits=[
    textHasNumber(evidenceText,labelKcal,0.04),
    textHasNumber(evidenceText,labelProt,0.04),
    textHasNumber(evidenceText,labelFat,0.04),
    textHasNumber(evidenceText,labelCarb,0.04)
  ].filter(Boolean).length;

  const labelEvidenceOk=completeLabel && evidenceHits>=3;

  // User-entered caption weight wins unconditionally.
  let grams=captionGrams;
  let weightSource=captionGrams?'caption':'missing';

  if(!(grams>0)){
    const candidates=[
      num(x.grams),
      num(x.serving_weight_g),
      num(x.label_serving_g),
      num(x.package_mass_g)
    ];
    const v=candidates.find(n=>Number.isFinite(n)&&n>0);
    if(v){grams=Math.round(v);weightSource='vision_or_package';}
  }

  const y={
    idx:i,
    dish,
    label_name:labelName,
    label_name_confidence:Number(x.label_name_confidence??x.confidence??0),
    label_name_locked:Boolean(packageContext&&labelName),
    name_source:Boolean(packageContext&&labelName)?'label':'vision',
    brand:txt(x.brand||x.store||x['brand/store']),
    user_caption_hint:captionHint,
    user_identity_locked:Boolean(captionHasIdentity&&arr.length===1),
    source_mode:mode,
    package_context:packageContext,
    package_text:packageText,
    grams:Number(grams||0),
    weight_missing:!(Number(grams)>0),
    weight_source:weightSource,
    confidence:Number(x.confidence??0.5),
    label_basis:
      x.label_basis==='per_serving'||x.label_basis==='serving'?'per_serving':
      x.label_basis==='per100g'?'per100g':null,
    label_serving_g:num(x.label_serving_g),
    label_kcal:labelKcal,
    label_prot:labelProt,
    label_fat:labelFat,
    label_carb:labelCarb,
    label_text:labelText,
    label_evidence_hits:evidenceHits,
    label_evidence_ok:labelEvidenceOk
  };

  if(captionHasIdentity&&arr.length===1){
    // A named product/store in the caption should be searched exactly.
    y.source_mode='web';
    y.name_source='caption';
    y.label_name_locked=false;
  }else if(packageContext&&labelEvidenceOk){
    y.source_mode='label';
  }else if(packageContext){
    // Do not trust uncertain OCR macros as authoritative label data.
    y.source_mode='web';
  }

  return y;
})
.filter(x=>Boolean(x.dish))
.slice(0,10)
.map((x,i)=>({...x,idx:i}));

return [{json:{
  chat_id:chatId,
  message_id:msgId,
  photo_file_id:photoId,
  containers_detected:containers,
  caption_grams:captionGrams,
  caption_identity_hint:captionHint,
  caption_has_identity:captionHasIdentity,
  recognition_started_at_ms:Number(cap.recognition_started_at_ms||Date.now()),
  items:clean,
  items_json:JSON.stringify(clean),
  avg_confidence:clean.length
    ?Math.round(clean.reduce((a,x)=>a+Math.max(0,Math.min(1,x.confidence||0)),0)/clean.length*100)/100
    :0,
  route:'single_pass',
  primary_raw:raw.slice(0,5000)
}}];

const source=$input.first().json;
const prep=$items('Prepare smart nutrition')[0].json;
// V14_CAPTION_LOCK
const lockedCaptionGrams=Number(prep.caption_grams||0)>0?Number(prep.caption_grams):null;


let raw=source.message?.content??source.output??source;
if(typeof raw==='string'){
  const s=raw.replace(/```json|```/g,'').trim();
  try{raw=JSON.parse(s)}
  catch(_){return [{json:{...prep,recognition_failed:true,route_nutrition:'recognition_failed'}}]}
}

const resolved=Array.isArray(raw.items)?raw.items:[];
const direct=Array.isArray(prep.direct_items)?prep.direct_items:[];
const unresolved=Array.isArray(prep.unresolved_items)?prep.unresolved_items:[];

const finite=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
const completeLabel=x=>
  finite(x.label_kcal)&&finite(x.label_prot)&&finite(x.label_fat)&&finite(x.label_carb);

function fromLabel(input,grams){
  if(!completeLabel(input)||!(grams>0))return null;

  let factor=null;
  if(input.label_basis==='per100g'){
    factor=grams/100;
  }else if(input.label_basis==='per_serving'){
    const serving=Number(input.label_serving_g||input.serving_weight_g||0);
    factor=serving>0?grams/serving:1;
  }
  if(factor===null)return null;

  const scale=v=>Math.round(Number(v)*factor*10)/10;
  return {
    kcal:scale(input.label_kcal),
    prot:scale(input.label_prot),
    fat:scale(input.label_fat),
    carb:scale(input.label_carb)
  };
}

const aiRows=unresolved.map((input,i)=>{
  const m=resolved.find(x=>Number(x.idx)===Number(input.idx))||resolved[i]||{};

  // Critical fix: allow lookup to supply grams when Vision could not.
  const inputGrams=Number(input.grams||0);
  const lookupGrams=Number(m.grams||0);
  const grams=lockedCaptionGrams || (inputGrams>0?inputGrams:lookupGrams);

  // If label K/B/F/C were photographed, web may supply weight only.
  const labelCalc=fromLabel(input,grams);
  const personal=input.override_found&&input.personal_override?input.personal_override:null;

  return {
    ...input,
    dish:String(input.label_name_locked&&input.label_name
      ? input.label_name
      : (m.dish||input.dish)),
    grams,
    weight_missing:!(grams>0),
    kcal:personal?Number(personal.kcal||0):(labelCalc?labelCalc.kcal:Number(m.kcal||0)),
    prot:personal?Number(personal.prot||0):(labelCalc?labelCalc.prot:Number(m.prot||0)),
    fat:personal?Number(personal.fat||0):(labelCalc?labelCalc.fat:Number(m.fat||0)),
    carb:personal?Number(personal.carb||0):(labelCalc?labelCalc.carb:Number(m.carb||0)),
    nutrition_source:personal?'personal_override':(labelCalc?'label':String(m.nutrition_source||(input.source_mode==='web'?'web':'estimate'))),
    source_url:String(m.source_url||''),
    source_title:labelCalc?'Этикетка на фото':String(m.source_title||'')
  };
});

const combined=[...direct,...aiRows]
  .sort((a,b)=>Number(a.idx)-Number(b.idx))
  .map((x,i)=>({...x,idx:i}));

function sanity(dish,grams,kcal){
  if(!(grams>0)||!(kcal>0))return {per100:0,ok:false};
  const per100=kcal/grams*100;
  const s=String(dish||'').toLowerCase();
  let min=5,max=900;
  if(/суп|борщ|щи|солян|бульон/.test(s)){min=10;max=260}
  else if(/салат|овощ/.test(s)){min=10;max=450}
  else if(/пюре|рис|греч|макарон|картоф|круп/.test(s)){min=40;max=420}
  else if(/кур|индей|рыб|мяс|филе|котлет|бургер/.test(s)){min=60;max=650}
  else if(/булоч|хлеб|лаваш|лепеш|выпеч|батончик/.test(s)){min=120;max=700}
  else if(/соус|майон|сметан|заправ/.test(s)){min=20;max=850}
  return {per100:Math.round(per100),ok:Number.isFinite(per100)&&per100>=min&&per100<=max};
}

const rows=combined.map((x,i)=>{
  const confidence=Number(x.confidence??0.5);
  const check=sanity(x.dish,Number(x.grams),Number(x.kcal));
  const grounded=['label','web','personal_override'].includes(String(x.nutrition_source));
  const missingWeight=!(Number(x.grams)>0);
  const lowConfidence=!grounded&&confidence<0.45;
  const uncertain=missingWeight||(!grounded&&confidence>=0.45&&confidence<0.75);
  const insane=missingWeight||!check.ok||Number(x.kcal)<=0;

  return {
    ...x,
    idx:i,
    uncertain,
    sanity_ok:check.ok,
    kcal_per_100g:check.per100,
    included:!lowConfidence&&!insane
  };
});

if(!rows.length)throw new Error('После определения КБЖУ нет блюд');

const included=rows.filter(x=>x.included);
const totals=included.reduce((a,r)=>({
  kcal:a.kcal+Number(r.kcal||0),
  prot:a.prot+Number(r.prot||0),
  fat:a.fat+Number(r.fat||0),
  carb:a.carb+Number(r.carb||0)
}),{kcal:0,prot:0,fat:0,carb:0});

const sourceMark=x=>x.nutrition_source==='label'?'🏷️':x.nutrition_source==='web'?'🌐':x.nutrition_source==='personal_override'?'🧠':'';
const lines=rows.map((r,i)=>{
  let marker=sourceMark(r);
  if(marker)marker+=' ';
  let suffix='';
  if(!(Number(r.grams)>0)){
    marker='⚠️ '+marker;
    suffix=' · не удалось определить массу';
  }else if(!r.included){
    marker='❓ '+marker;
    suffix=' · не учитываю';
  }else if(r.uncertain){
    marker='⚠️ '+marker;
    suffix=' · проверь';
  }
  return `${i+1}. ${marker}${r.dish} — ${Number(r.grams)>0?'~'+Math.round(r.grams)+' г':'масса ?'} · ${Math.round(r.kcal||0)} ккал${suffix}`;
});

const labelCount=rows.filter(x=>x.nutrition_source==='label').length;
const webCount=rows.filter(x=>x.nutrition_source==='web').length;
const memoryCount=rows.filter(x=>x.nutrition_source==='personal_override').length;
const warningCount=rows.filter(x=>x.uncertain||!x.included).length;
const foodConfidence=rows.length?rows.reduce((a,x)=>a+Math.max(0,Math.min(1,Number(x.confidence||0))),0)/rows.length:0;
const portionConfidence=rows.length?rows.reduce((a,x)=>a+(Number(x.grams)>0?(x.weight_source==='caption'?1:0.72):0.15),0)/rows.length:0;
