const finite=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));

function completeTrustedLabel(x){
  return x.label_evidence_ok===true &&
    finite(x.label_kcal)&&finite(x.label_prot)&&finite(x.label_fat)&&finite(x.label_carb);
}

function directFromLabel(x){
  if(!completeTrustedLabel(x))return null;

  const grams=Number(x.grams||0);
  if(!(grams>0))return null;

  let factor=null;
  if(x.label_basis==='per100g'){
    factor=grams/100;
  }else if(x.label_basis==='per_serving'){
    const serving=Number(x.label_serving_g||0);
    factor=serving>0?grams/serving:1;
  }
  if(factor===null)return null;

  const scale=v=>Math.round(Number(v)*factor*10)/10;

  return {
    ...x,
    source_mode:'label',
    kcal:scale(x.label_kcal),
    prot:scale(x.label_prot),
    fat:scale(x.label_fat),
    carb:scale(x.label_carb),
    nutrition_source:'label',
    source_url:'',
    source_title:'Этикетка на фото'
  };
}

