    x.name_source='label';
  }

  if(x.override_found&&x.personal_override){
    direct.push({
      ...x,
      source_mode:'personal_override',
      nutrition_source:'personal_override',
      kcal:Number(x.personal_override.kcal||0),
      prot:Number(x.personal_override.prot||0),
      fat:Number(x.personal_override.fat||0),
      carb:Number(x.personal_override.carb||0),
      source_url:'',
      source_title:'Подтверждено пользователем ранее',
      confidence:Math.max(Number(x.confidence||0),Number(x.override_confidence||.95))
    });
    continue;
  }

  const directLabel=directFromLabel(x);
  if(directLabel){
    direct.push(directLabel);
    continue;
  }

  unresolved.push(x);
}

