if(action==='next')idx=(idx+1)%items2.length;
if(action==='prev')idx=(idx-1+items2.length)%items2.length;

function setWeight(x,next){
  const old=Number(x.grams||0);
  next=Math.max(1,Math.min(3000,Math.round(next)));

  if(old>0){
    const ratio=next/old;
    for(const k of ['kcal','prot','fat','carb'])
      x[k]=Math.round(Number(x[k]||0)*ratio*10)/10;
  }else if(
    x.nutrition_source==='label' &&
    x.label_basis==='per100g' &&
